functions._alpSections:
function _alpSections() {
  return [
    { key: "playbooks",    storeName: "playbooks",    manifestId: "__data_playbooks_proprietary",     filename: "playbooks.enc.json",    label: "Playbooks" },
    { key: "requesters",   storeName: "requesters",   manifestId: "__data_requesters_proprietary",    filename: "requesters.enc.json",   label: "Requesters" },
    { key: "riskRules",    storeName: "risk_rules",   manifestId: "__data_risk_rules_proprietary",    filename: "riskRules.enc.json",    label: "Risk Rules" },
    { key: "templates",    storeName: "templates",    manifestId: "__data_templates_proprietary",     filename: "templates.enc.json",    label: "Compare Draft Templates" },
    { key: "bd_templates", storeName: "bd_templates", manifestId: "__data_bd_templates_proprietary",  filename: "bd_templates.enc.json", label: "Build Draft Templates" }
  ];
}

functions._alpStrToB64:
function _alpStrToB64(s) {
  var bytes = new TextEncoder().encode(s);
  var bin = "";
  for (var i = 0; i < bytes.length; i++) bin += String.fromCharCode(bytes[i]);
  return btoa(bin);
}

// GET /repos/.../contents/<path> → returns parsed JSON content + sha (or null
// if 404). Used to fetch the existing manifest before update, and to pick up
// the SHA needed to PUT an existing file.

functions._alpGitHubGet:
function _alpGitHubGet(pat, repo, branch, filePath) {
  var url = "https://api.github.com/repos/" + repo + "/contents/" + filePath +
    "?ref=" + encodeURIComponent(branch);
  return fetch(url, {
    headers: {
      "Authorization": "Bearer " + pat,
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
    },
  }).then(function (r) {
    if (r.status === 404) return null;
    if (!r.ok) return r.text().then(function (t) { throw new Error("GET " + filePath + " failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
    return r.json();
  });
}

// PUT /repos/.../contents/<path> — creates or updates a file. Pass existingSha
// from a prior GET to update; omit to create new.

functions._alpGitHubPut:
function _alpGitHubPut(pat, repo, branch, filePath, contentStr, message, existingSha) {
  var url = "https://api.github.com/repos/" + repo + "/contents/" + filePath;
  var body = {
    message: message,
    content: _alpStrToB64(contentStr),
    branch: branch,
  };
  if (existingSha) body.sha = existingSha;
  return fetch(url, {
    method: "PUT",
    headers: {
      "Authorization": "Bearer " + pat,
      "Accept": "application/vnd.github+json",
      "X-GitHub-Api-Version": "2022-11-28",
      "Content-Type": "application/json",
    },
    body: JSON.stringify(body),
  }).then(function (r) {
    if (!r.ok) return r.text().then(function (t) { throw new Error("PUT " + filePath + " failed: HTTP " + r.status + " · " + t.slice(0, 200)); });
    return r.json();
  });
}

// Encrypt a section straight from IDB. Produces the same envelope shape as
// build_encrypted_<section>.js / encrypt_library.js — { v:1, salt, iv, ct } —
// so _eliDecryptFromRepo on download is unchanged.

functions._alpEncryptSection:
function _alpEncryptSection(sectionKey, version) {
  var cipher = (typeof window._eliGetLibraryCipher === "function") ? window._eliGetLibraryCipher() : "";
  if (!cipher) return Promise.reject(new Error("no library cipher set — Settings → Global → 📦 LIBRARY CIPHER"));
  var sec = _alpSections().find(function (s) { return s.key === sectionKey; });
  if (!sec) return Promise.reject(new Error("unknown section: " + sectionKey));
  if (typeof loadFeatureData !== "function") return Promise.reject(new Error("loadFeatureData unavailable"));
  return loadFeatureData(sec.storeName).then(function (rows) {
    if (!Array.isArray(rows)) rows = [];
    var envelope = {
      schemaVersion: 1,
      exportedAt: new Date().toISOString(),
      sectionVersions: {},
      sections: {},
    };
    envelope.sectionVersions[sectionKey] = version;
    envelope.sections[sectionKey] = rows;
    return window._eliEncryptForRepo(cipher, envelope).then(function (encrypted) {
      var json = JSON.stringify(encrypted, null, 2);
      return {
        encryptedJson: json,
        encryptedSize: new TextEncoder().encode(json).length,
        rowCount: rows.length,
        plaintextSize: JSON.stringify(envelope).length,
      };
    });
  });
}

// Full publish flow for one section: encrypt → PUT blob → fetch+update+PUT
// manifest. Returns a result object for the UI log.

functions._alpPushOne:
function _alpPushOne(sectionKey, version, commitNote, logEl) {
  var pat = _alpGetPat(); if (!pat) return Promise.reject(new Error("no GitHub PAT — set it in this tool's settings"));
  var repo = _alpGetRepo(); var branch = _alpGetBranch();
  var sec = _alpSections().find(function (s) { return s.key === sectionKey; });
  var append = function (msg) {
    if (logEl) {
      logEl.innerHTML += '<div style="font-size:10px; color:#475569; margin-top:2px;">' + msg + '</div>';
      logEl.scrollTop = logEl.scrollHeight;
    }
  };
  append("📦 [" + sec.label + "] Encrypting from IDB…");
  return _alpEncryptSection(sectionKey, version).then(function (enc) {
    append("✓ Encrypted: " + enc.rowCount + " rows · " + (enc.plaintextSize / 1024).toFixed(1) + " KB plaintext → " + (enc.encryptedSize / 1024).toFixed(1) + " KB ciphertext");
    append("⬆️ Fetching existing " + sec.filename + " (for SHA)…");
    return _alpGitHubGet(pat, repo, branch, sec.filename).then(function (existing) {
      var sha = existing && existing.sha;
      append(sha ? "  found existing — sha " + sha.slice(0, 8) + "…" : "  not present — creating new");
      append("⬆️ Pushing " + sec.filename + "…");
      var msg = "Update " + sec.filename + " · v" + version + " · " + enc.rowCount + " rows" + (commitNote ? " · " + commitNote : "");
      return _alpGitHubPut(pat, repo, branch, sec.filename, enc.encryptedJson, msg, sha).then(function () {
        append("✓ " + sec.filename + " pushed");
        append("⬆️ Updating manifest entry " + sec.manifestId + "…");
        return _alpGitHubGet(pat, repo, branch, "tools-manifest-v2.json").then(function (manifestRes) {
          if (!manifestRes) throw new Error("manifest not found in repo");
          var manifestStr = atob((manifestRes.content || "").replace(/\s/g, ""));
          var manifestJson = JSON.parse(manifestStr);
          var entry = (manifestJson.tools || []).find(function (t) { return t.id === sec.manifestId; });
          if (!entry) throw new Error("manifest has no entry for " + sec.manifestId + " — add it manually first");
          entry.version = version;
          entry.size = enc.encryptedSize;
          entry.changelog = "v" + version + " · " + enc.rowCount + " rows · pushed " + new Date().toISOString().slice(0, 19) + "Z" + (commitNote ? " · " + commitNote : "");
          manifestJson.lastUpdated = new Date().toISOString();
          var newManifest = JSON.stringify(manifestJson, null, 2);
          return _alpGitHubPut(pat, repo, branch, "tools-manifest-v2.json", newManifest,
            "Bump " + sec.manifestId + " to v" + version, manifestRes.sha).then(function () {
            append("✅ Manifest updated — " + sec.label + " v" + version + " is live");
            return { sectionKey: sectionKey, version: version, encryptedSize: enc.encryptedSize, rowCount: enc.rowCount };
          });
        });
      });
    });
  }).catch(function (err) {
    append('<span style="color:#dc2626; font-weight:700;">❌ ' + (err && err.message ? err.message : "unknown error") + '</span>');
    throw err;
  });
}

functions.showAdminLibraryPublisher:
function showAdminLibraryPublisher() {
  var out = document.getElementById("output");
  if (!out) return;
  out.innerHTML = "";
  out.classList.remove("hidden");
  out.classList.add("eli-view-enter");
  var header = (typeof createConfigHeader === "function")
    ? createConfigHeader("ADMIN — RESTRICTED", "🛠️", "Admin Library Publisher", { marginBottom: "12px" })
    : null;
  if (header) out.appendChild(header);
  var card = document.createElement("div");
  card.style.cssText = "padding:0; border:1px solid #d1d5db; border-left:5px solid #7c2d12; background:#fff; margin-bottom:12px;";
  card.innerHTML =
    '<div style="padding:12px 14px; border-bottom:1px solid #e5e7eb; background:#fff7ed;">' +
      '<div style="font-size:10px; font-weight:800; color:#7c2d12; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:4px;">⚠️ Internal admin tool — push to public GitHub repo</div>' +
      '<div style="font-size:11px; color:#475569; line-height:1.45;">' +
        'Encrypts each selected library straight from your IDB using the library cipher in Settings → Global, then PUTs the encrypted blob and updates the manifest entry via the GitHub Contents API. Confirm your <b>library cipher</b> is set BEFORE pushing — without it the encryption will fail.' +
      '</div>' +
    '</div>' +
    '<div style="padding:12px 14px;">' +
      '<div style="font-size:10px; font-weight:700; color:#0f172a; margin-bottom:4px; text-transform:uppercase; letter-spacing:0.4px;">GitHub Personal Access Token (fine-grained)</div>' +
      '<div style="display:flex; gap:4px; align-items:center; margin-bottom:4px;">' +
        '<input type="password" id="alpPat" placeholder="github_pat_..." style="flex:1; padding:6px 8px; font-size:11px; border:1px solid #ced4da; border-radius:4px; font-family:monospace; box-sizing:border-box;">' +
        '<button id="alpPatToggle" title="Show/Hide" style="padding:6px 10px; font-size:11px; border:1px solid #ced4da; border-radius:4px; cursor:pointer;">👁️</button>' +
        '<button id="alpPatSave" style="padding:6px 12px; font-size:11px; border:none; border-radius:4px; background:#7c2d12; color:#fff; cursor:pointer; font-weight:bold;">Save</button>' +
      '</div>' +
      '<div id="alpPatStatus" style="font-size:10px; color:#888; margin-bottom:10px; min-height:14px;"></div>' +
      '<div style="display:flex; gap:8px; margin-bottom:10px;">' +
        '<div style="flex:2;">' +
          '<div style="font-size:10px; font-weight:700; color:#0f172a; margin-bottom:3px; text-transform:uppercase; letter-spacing:0.4px;">Repo</div>' +
          '<input type="text" id="alpRepo" placeholder="owner/repo" style="width:100%; padding:6px 8px; font-size:11px; border:1px solid #ced4da; border-radius:4px; font-family:monospace; box-sizing:border-box;">' +
        '</div>' +
        '<div style="flex:1;">' +
          '<div style="font-size:10px; font-weight:700; color:#0f172a; margin-bottom:3px; text-transform:uppercase; letter-spacing:0.4px;">Branch</div>' +
          '<input type="text" id="alpBranch" placeholder="main" style="width:100%; padding:6px 8px; font-size:11px; border:1px solid #ced4da; border-radius:4px; font-family:monospace; box-sizing:border-box;">' +
        '</div>' +
      '</div>' +
      '<div style="font-size:10px; font-weight:700; color:#0f172a; margin-bottom:3px; text-transform:uppercase; letter-spacing:0.4px;">Commit note (optional)</div>' +
      '<input type="text" id="alpCommitNote" placeholder="e.g. added 5 new requesters" style="width:100%; padding:6px 8px; font-size:11px; border:1px solid #ced4da; border-radius:4px; box-sizing:border-box; margin-bottom:10px;">' +
    '</div>';
  out.appendChild(card);
  // Section list
  var listCard = document.createElement("div");
  listCard.style.cssText = "border:1px solid #d1d5db; background:#fff; margin-bottom:12px;";
  listCard.innerHTML =
    '<div style="padding:8px 12px; background:linear-gradient(135deg,#0f172a,#1e293b); color:#fff; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.6px; display:flex; justify-content:space-between; align-items:center;">' +
      '<span>Select libraries to push</span>' +
      '<span style="font-size:10px; font-weight:600; opacity:0.8;">Manifest v→ next</span>' +
    '</div>' +
    '<div id="alpSectionRows"></div>' +
    '<div style="padding:10px 12px; border-top:1px solid #e5e7eb; display:flex; gap:8px; align-items:center;">' +
      '<button id="alpPushSelected" style="flex:1; padding:9px; font-size:11px; font-weight:800; text-transform:uppercase; letter-spacing:0.4px; cursor:pointer; background:linear-gradient(135deg,#7c2d12,#5b1a02); color:#fff; border:1.5px solid #5b1a02; border-radius:0;">⬆️ Encrypt & Push selected</button>' +
      '<button id="alpRefreshVersions" title="Re-fetch current manifest versions" style="padding:9px 12px; font-size:11px; font-weight:700; cursor:pointer; background:#fff; color:#475569; border:1px solid #cbd5e1; border-radius:0;">🔄</button>' +
    '</div>';
  out.appendChild(listCard);
  // Log
  var logCard = document.createElement("div");
  logCard.style.cssText = "border:1px solid #d1d5db; background:#0f172a; color:#cbd5e1; padding:10px 12px; font-family:ui-monospace,Consolas,monospace; max-height:280px; overflow-y:auto;";
  logCard.innerHTML = '<div style="font-size:10px; font-weight:800; color:#fff; text-transform:uppercase; letter-spacing:0.5px; margin-bottom:6px;">▼ Push log</div><div id="alpLog" style="font-size:10px; line-height:1.5;"></div>';
  out.appendChild(logCard);
  // Wire fields
  document.getElementById("alpPat").value = _alpGetPat();
  document.getElementById("alpRepo").value = _alpGetRepo();
  document.getElementById("alpBranch").value = _alpGetBranch();
  function _alpRefreshPatStatus() {
    var p = _alpGetPat();
    var s = document.getElementById("alpPatStatus");
    if (s) {
      s.innerHTML = p
        ? '<span style="color:#166534; font-weight:bold;">✅ PAT saved (' + p.length + ' chars)</span>'
        : '<span style="color:#b91c1c;">⚠️ No PAT — pushes will fail</span>';
    }
  }
  _alpRefreshPatStatus();
  document.getElementById("alpPatToggle").onclick = function () {
    var f = document.getElementById("alpPat");
    f.type = f.type === "password" ? "text" : "password";
  };
  document.getElementById("alpPatSave").onclick = function () {
    _alpSetPat(document.getElementById("alpPat").value.trim());
    _alpSetRepo(document.getElementById("alpRepo").value.trim());
    _alpSetBranch(document.getElementById("alpBranch").value.trim());
    _alpRefreshPatStatus();
    if (typeof showToast === "function") showToast("✓ Saved PAT + repo settings", "success");
  };
  // Render section rows + populate version columns
  function _alpRenderRows(manifestEntries) {
    var byId = {};
    (manifestEntries || []).forEach(function (e) { byId[e.id] = e; });
    var rowsHtml = _alpSections().map(function (s, idx) {
      var stripe = idx % 2 === 0 ? "#ffffff" : "#f8fafc";
      var cur = byId[s.manifestId];
      var curV = cur ? Number(cur.version) || 0 : 0;
      var nextV = curV + 1;
      var rowCount = "—";
      return (
        '<div style="display:grid; grid-template-columns:auto 1fr auto auto; gap:10px; align-items:center; padding:8px 12px; background:' + stripe + '; border-bottom:1px solid #f1f5f9;">' +
          '<input type="checkbox" class="alp-sec-check" data-alp-key="' + s.key + '" style="cursor:pointer; margin:0;">' +
          '<div>' +
            '<div style="font-size:11px; font-weight:700; color:#0f172a;">🔒 ' + s.label + '</div>' +
            '<div style="font-size:9px; color:#94a3b8; font-family:monospace; margin-top:1px;">' + s.manifestId + '</div>' +
          '</div>' +
          '<div style="font-size:10px; color:#64748b; text-align:right;">v' + curV + '</div>' +
          '<div style="font-size:10px; font-weight:700; color:#7c2d12; text-align:right; min-width:30px;">→ v<input type="number" class="alp-sec-ver" data-alp-key="' + s.key + '" value="' + nextV + '" min="' + Math.max(1, curV + 1) + '" style="width:40px; padding:2px 4px; font-size:11px; border:1px solid #cbd5e1; border-radius:3px; font-family:monospace; text-align:center;"></div>' +
        '</div>'
      );
    }).join("");
    var rowsEl = document.getElementById("alpSectionRows");
    if (rowsEl) rowsEl.innerHTML = rowsHtml;
  }
  function _alpRefreshFromManifest() {
    var pat = _alpGetPat(), repo = _alpGetRepo(), branch = _alpGetBranch();
    if (!pat) {
      _alpRenderRows([]);
      var rowsEl = document.getElementById("alpSectionRows");
      if (rowsEl) rowsEl.insertAdjacentHTML("beforeend", '<div style="padding:8px 12px; font-size:10px; color:#b91c1c;">⚠️ Save a PAT to fetch current manifest versions.</div>');
      return;
    }
    _alpGitHubGet(pat, repo, branch, "tools-manifest-v2.json").then(function (mres) {
      if (!mres) { _alpRenderRows([]); return; }
      try {
        var m = JSON.parse(atob((mres.content || "").replace(/\s/g, "")));
        _alpRenderRows(m.tools || []);
      } catch (_) { _alpRenderRows([]); }
    }).catch(function (err) {
      _alpRenderRows([]);
      var log = document.getElementById("alpLog");
      if (log) log.innerHTML += '<div style="color:#fca5a5;">manifest fetch failed: ' + (err && err.message ? err.message : "unknown") + '</div>';
    });
  }
  _alpRefreshFromManifest();
  document.getElementById("alpRefreshVersions").onclick = _alpRefreshFromManifest;
  document.getElementById("alpPushSelected").onclick = function () {
    var checked = document.querySelectorAll(".alp-sec-check:checked");
    if (!checked.length) {
      if (typeof showToast === "function") showToast("Pick at least one section.", "info");
      return;
    }
    if (!_alpGetPat()) {
      if (typeof showToast === "function") showToast("⚠️ Save a GitHub PAT first.", "error");
      return;
    }
    if (typeof window._eliGetLibraryCipher === "function" && !window._eliGetLibraryCipher()) {
      if (typeof showToast === "function") showToast("⚠️ Set the library cipher in Settings → Global first.", "error");
      return;
    }
    var note = (document.getElementById("alpCommitNote").value || "").trim();
    var picks = [];
    Array.prototype.forEach.call(checked, function (cb) {
      var key = cb.getAttribute("data-alp-key");
      var verEl = document.querySelector('.alp-sec-ver[data-alp-key="' + key + '"]');
      var ver = Math.max(1, Number(verEl && verEl.value) || 1);
      picks.push({ key: key, version: ver });
    });
    var btn = this;
    btn.disabled = true;
    btn.textContent = "⏳ Pushing…";
    var logEl = document.getElementById("alpLog");
    logEl.innerHTML += '<div style="color:#fff; margin-top:8px; font-weight:800;">━━━ Push run started · ' + new Date().toLocaleString() + ' ━━━</div>';
    // Sequential to avoid GitHub rate limits + manifest write conflicts
    // (each push reads + updates the manifest, so they must serialize).
    var i = 0, succeeded = 0;
    var next = function () {
      if (i >= picks.length) {
        btn.disabled = false;
        btn.textContent = "⬆️ Encrypt & Push selected";
        logEl.innerHTML += '<div style="color:#86efac; margin-top:6px; font-weight:800;">━━━ Done · ' + succeeded + ' / ' + picks.length + ' succeeded ━━━</div>';
        if (typeof showToast === "function") showToast(succeeded + " / " + picks.length + " library push" + (picks.length === 1 ? "" : "es") + " complete", succeeded === picks.length ? "success" : "error");
        _alpRefreshFromManifest();
        return;
      }
      var p = picks[i++];
      _alpPushOne(p.key, p.version, note, logEl).then(function () {
        succeeded++; next();
      }).catch(function () { next(); });
    };
    next();
  };
}
